from pathlib import Path
from PIL import Image,ImageDraw
import numpy as np,base64,json,html
P=Path(__file__).parent;(P/'zoom').mkdir(exist_ok=True);W,H=1100,5*260+45
backgrounds={'opaque':'#e1dbc8','dark':'#102331','transparent':None};roi=(445,465,650,580)
for bg,color in backgrounds.items():
 sheet=Image.new('RGB',(W,H),color or '#e4e4e4');d=ImageDraw.Draw(sheet)
 if color is None:
  for y in range(0,H,16):
   for x in range(0,W,16):
    if (x//16+y//16)%2:d.rectangle((x,y,x+15,y+15),fill='#b6b6b6')
 d.text((10,8),'Phase / before96 / after96 / before neck2x / after neck2x. Rigged source pixels; owner art review pending.',fill='white' if bg=='dark' else 'black')
 for i in range(5):
  y=45+i*260;d.text((6,y),str(i),fill='white' if bg=='dark' else 'black')
  for label,filename,x in [('before',f'before/rig-frame-{i:02}.png',35),('after',f'frames-native1024/{i:02}.png',145)]:
   im=Image.open(P/filename).convert('RGBA');small=im.resize((96,96),Image.Resampling.NEAREST);sheet.paste(small,(x,y+18),small);zoom=im.crop(roi).resize((410,230),Image.Resampling.NEAREST);zx=260 if label=='before' else 680;sheet.paste(zoom,(zx,y+18),zoom)
   im.crop(roi).save(P/'zoom'/f'{label}-{i:02}.png')
 sheet.save(P/f'before-after-{bg}.png')
def uri(path):return 'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()
review=json.loads((P/'occlusion-review.json').read_text());meta=json.loads((P/'export-metadata.json').read_text())
s='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Finch rig: neck-layer cleanup</title><style>body{font:17px/1.5 system-ui;background:#142a27;color:#f0ead8;max-width:1200px;margin:auto;padding:24px}h1{line-height:1.1}strong{color:#ffbd99}img{image-rendering:pixelated;max-width:100%}select,button,input{font:inherit}table{border-collapse:collapse}th,td{padding:7px;border:1px solid #607268}pre{font-size:13px;white-space:pre-wrap}.pair{display:flex;gap:12px;align-items:start;flex-wrap:wrap}.tile{display:inline-block;background:#e1dbc8;line-height:0}.tile.checker{background:conic-gradient(#b6b6b6 25%,#e4e4e4 0 50%,#b6b6b6 0 75%,#e4e4e4 0) 0/16px 16px}.zoom{width:410px}.normal{width:96px}</style><h1>Finch neck overlap: explicit layer cleanup</h1><p><strong>Rigged source reuse. Zero new drawings or generation calls. Owner art review still required.</strong> A separate editable neck mask retains original neck pixels behind the head cutout. Protected body/feet y≥600 remain byte-identical. No feather painting, body fitting or new renderer was added.</p><p>Normal-size comparison uses a proposed96px whole canvas; biological/world scale is unapproved. Neck zoom is2× source pixels from x445..649,y465..579.</p><label>Background <select id="background"><option value="opaque">Opaque cream</option><option value="transparent">Transparent / checker</option><option value="dark">Dark</option></select></label> <label>Phase <input id="phase" type="range" min="0" max="4" value="0"></label> <button id="play">Play</button><div id="phaseText"></div><div class="pair"><div><p>Before96</p><div class="tile"><img id="bn" class="normal"></div></div><div><p>After96</p><div class="tile"><img id="an" class="normal"></div></div><div><p>Before neck2×</p><div class="tile"><img id="bz" class="zoom"></div></div><div><p>After neck2×</p><div class="tile"><img id="az" class="zoom"></div></div></div><h2>All five phases</h2><img id="sheet"><h2>Occlusion evidence</h2><table><tr><th>Phase</th><th>Angle</th><th>Before neck gaps</th><th>After neck gaps</th><th>Remaining whole rest-mask difference</th><th>Protected changes</th></tr>'''
for e in review['allFivePhases']:s+='<tr>'+''.join('<td>'+str(e[k])+'</td>' for k in ['phase','angleRadians','beforeNeckRegionUncoveredPixels','afterNeckRegionUncoveredPixels','afterWholeRestMaskUncoveredPixels','protectedRGBAChangedPixels'])+'</tr>'
s+='''</table><p>Large neck cutout gaps are covered. Phase1 retains144 alpha≥128 uncovered source pixels in the unchanged neck test region after excluding the old bill; owner review remains required. The whole-rest-mask metric remains nonzero for rotated heads: it includes expected crown/bill silhouette changes and is not relabeled as a pass. Retained underpaint can create stale jaw/neck contours or doubled feather edges. Head stays in front in every phase; behind-body/depth/wing occlusion and broader turns are unsupported. Neutral phases0,2,4 copy the original exactly.</p><p><strong>Owner review: source rectangle[445,465,650,580], especially phase1 jaw rectangle[607, 475, 633, 492] and phase3 feather overlap.</strong> Judge jaw/back-neck edge, feather overlap and lighting on all three backgrounds. Numerical hole closure does not approve the seam.</p><h2>96px contract review export</h2><p>Fixed whole-canvas3/32 resize, shared palette and binary alpha;5×96²=46,080 decoded pixels. This derivative is explicitly lossy. It passes the retained image-stage JSON schema and mechanical checks; source palette-preservation, species/rights/reference pins, scale/tick mapping and Mac playback are not approved. No production runtime manifest is fabricated.</p><div class="pair">'''
for i in range(5):s+='<div class="tile"><img width="96" src="'+uri(P/'export96'/f'{i:02}.png')+'"></div>'
s+='</div><h3>Marked phase1 jaw region</h3><img width=600 alt="Owner review annotation, not source art" src="'+uri(P/'owner-review-jaw-phase01.png')+'"><details><summary>Layer edit plan</summary><pre>'+html.escape((P/'layer-edit-plan.json').read_text())+'</pre></details><details><summary>Export metadata</summary><pre>'+html.escape((P/'export-metadata.json').read_text())+'</pre></details>'
images={id:[uri(P/(prefix+f'{i:02}.png')) for i in range(5)] for id,prefix in [('bn','before/rig-frame-'),('an','frames-native1024/'),('bz','zoom/before-'),('az','zoom/after-')]};s+='<script>const images='+json.dumps(images)+';const sheets='+json.dumps({k:uri(P/f'before-after-{k}.png') for k in backgrounds})+';</script>'
s+='''<script>let phase=0,playing=false;function draw(k){phase=k;for(const id of Object.keys(images))document.getElementById(id).src=images[id][k];document.getElementById('phase').value=k;document.getElementById('phaseText').textContent='Phase '+k+' — '+[0,-.12,0,.12,0][k]+' radians; head-over-neck only';window.currentPhase=k;}function background(){const v=document.getElementById('background').value;for(const t of document.querySelectorAll('.tile')){t.classList.toggle('checker',v==='transparent');t.style.backgroundColor=v==='dark'?'#102331':v==='opaque'?'#e1dbc8':'transparent';}document.getElementById('sheet').src=sheets[v];}document.getElementById('phase').oninput=e=>{playing=false;draw(+e.target.value)};document.getElementById('background').onchange=background;document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'Pause':'Play'};setInterval(()=>{if(playing)draw((phase+1)%5)},160);window.proofDraw=draw;draw(0);background();</script>'''
(P/'review.html').write_text(s);print('review.html and three five-phase comparison sheets built')
